#include <iostream>
#include <iomanip>

int main() {
    int account = 0;
    std::cout << std::fixed << std::setprecision(2);

    while (std::cin >> account && account != -1) {
        double balance = 0.0;
        double charges = 0.0;
        double credits = 0.0;
        double creditLimit = 0.0;

        std::cin >> balance >> charges >> credits >> creditLimit;

        double newBalance = balance + charges - credits;

        std::cout << "Account:      " << account << "\n";
        std::cout << "Credit limit: " << creditLimit << "\n";
        std::cout << "Balance:      " << newBalance << "\n";

        if (newBalance > creditLimit) {
            std::cout << "Credit Limit Exceeded.\n";
        }
    }

    return 0;
}

#include <iostream>

int main() {
    int count = 0;
    int largest = -1;
    int secondLargest = -1;
    int number = 0;

    while (count < 5 && std::cin >> number) {
        if (number > largest) {
            secondLargest = largest;
            largest = number;
        } else if (number > secondLargest) {
            secondLargest = number;
        }
        ++count;
    }

    std::cout << "Largest: " << largest << "\n";
    std::cout << "Second Largest: " << secondLargest << "\n";
    return 0;
}
